var i=`1306-empanadas-saltenas`;var t=`world-1306`;var a=`AR`;var o=`south-america`;var r=8;var s=94;var g={en:`Empanadas Salteñas`,ua:`Емпанадас сальтеньяс`};var l={en:`Empanadas Salteñas is a dish from Argentina featuring all-purpose flour, ground beef, yellow onion, chicken egg. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Емпанадас сальтеньяс, страва кухні країни Аргентина з такими основними складниками: пшеничне борошно універсальне, яловичий фарш, жовта цибуля, куряче яйце. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 20 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 20 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:20,i:[[`all-purpose-flour`,540,`g`],[`lard`,125,`g`],[`water`,220,`ml`],[`table-salt`,8,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:22,i:[[`ground-beef`,650,`g`],[`yellow-onion`,260,`g`],[`sweet-paprika`,12,`g`],[`ground-cumin`,6,`g`],[`chicken-egg`,2,`pcs`],[`green-olives`,80,`g`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:17,i:[]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 35 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 35 хвилин до готовності.`,t:[`baking`],m:35,i:[]}];var d={slug:i,id:t,country:`AR`,region:o,servings:8,minutes:94,title:g,text:l,steps:u};export{a as country,d as default,t as id,s as minutes,o as region,r as servings,i as slug,u as steps,l as text,g as title};